tool_input.command:
cd <repo>/internal/daemon && python3 - <<'EOF'
p='templates.go'
s=open(p).read()
old=s[s.index('\tif _, err := f.WriteString(prompt); err != nil {'):s.index('\treturn path, nil\n}', s.index('f.WriteString(prompt)'))]
new='''	if _, err := f.WriteString(prompt); err != nil {
		_ = f.Close()
		return "", removeAfterFailure(path, fmt.Errorf("write system prompt to %s: %w", path, err))
	}
	if err := f.Close(); err != nil {
		return "", removeAfterFailure(path, fmt.Errorf("close system prompt %s: %w", path, err))
	}
'''
s=s.replace(old,new)
s+='''
// removeAfterFailure removes path and returns cause joined with any removal
// error. The file may hold sender content, so a failed removal must leave a
// trace in the returned error rather than vanish.
func removeAfterFailure(path string, cause error) error {
	if rmErr := os.Remove(path); rmErr != nil {
		return errors.Join(cause, fmt.Errorf("remove %s: %w", path, rmErr))
	}
	return cause
}
'''
open(p,'w').write(s)
EOF
head -25 templates.go | grep -n '"errors"\|import'; grep -n "^func Test" templates_test.go | head -3; sed -n 1,25p templates_test.go

cd <repo>/internal/daemon && cat >> templates_test.go <<'EOF'

func TestRemoveAfterFailure(t *testing.T) {
	cause := errors.New("disk full")

	t.Run("removes the file and returns the cause alone", func(t *testing.T) {
		path := filepath.Join(t.TempDir(), "prompt.txt")
		require.NoError(t, os.WriteFile(path, []byte("sender content"), 0o600))

		err := removeAfterFailure(path, cause)
		assert.Equal(t, cause, err)
		assert.NoFileExists(t, path)
	})

	t.Run("joins the removal error when removal fails", func(t *testing.T) {
		// A non-empty directory cannot be removed by os.Remove.
		dir := filepath.Join(t.TempDir(), "stuck")
		require.NoError(t, os.Mkdir(dir, 0o700))
		require.NoError(t, os.WriteFile(filepath.Join(dir, "f"), nil, 0o600))

		err := removeAfterFailure(dir, cause)
		require.Error(t, err)
		assert.ErrorIs(t, err, cause)
		assert.Contains(t, err.Error(), "remove "+dir)
	})
}
EOF
gofmt -l .; go test -race -count=1 -run 'RemoveAfterFailure|SystemPrompt' . 2>&1 | grep -E "^(--- FAIL|ok|FAIL)|Error"
